async (page) => {
  const br = page.context().browser();
  const ctx = await br.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const pc = await ctx.newPage();
  await pc.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await pc.waitForTimeout(7000);
  await pc.locator('button.cinematic-model').first().click();
  await pc.waitForTimeout(1800);
  const res = await pc.evaluate(() => {
    const items = Array.from(document.querySelectorAll('[class*=model]')).filter(e => { const r = e.getBoundingClientRect(); return r.width > 60 && r.height > 20 && r.y > 100; }).slice(0, 12).map(e => ({cls: String(e.className).slice(0, 90), t: (e.innerText||'').trim().slice(0, 40).replace(/\n+/g,' / '), y: Math.round(e.getBoundingClientRect().y)}));
    const opts = Array.from(document.querySelectorAll('div,li')).filter(d => { const t=(d.innerText||'').trim(); return t.length>3 && t.length<60 && /Nano Banana|Seedream|Pokecut|ChatGPT/.test(t) && !t.includes('\n'); }).slice(0, 14).map(d => ({cls: String(d.className).slice(0, 70), t: d.innerText.trim().slice(0,40)}));
    return {modelEls: items, optionEls: opts};
  });
  await ctx.close();
  return JSON.stringify(res);
}
